fn numpy_greater_equal(x1: Vec<i8>, x2: Vec<i8>) -> Vec<bool> {
    assert_eq!(
        x1.len(),
        x2.len(),
        "Input vectors must have the same length"
    );
    x1.into_iter()
      .zip(x2.into_iter())
      .map(|(a, b)| a >= b)
      .collect()
}

